#!/usr/bin/env tsx
/**
 * Generate API types from OpenAPI specification
 * 
 * Reads: backend/storage/api-docs/api-docs.json (generated by L5-Swagger)
 * Writes: packages/types/src/api/generated.ts
 * 
 * Run: pnpm --filter types generate
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT_DIR = resolve(__dirname, '../../..');
const BACKEND_DIR = resolve(ROOT_DIR, 'backend');
const OPENAPI_PATH = resolve(BACKEND_DIR, 'storage/api-docs/api-docs.json');
const OUTPUT_DIR = resolve(__dirname, '../src/api');
const OUTPUT_PATH = resolve(OUTPUT_DIR, 'generated.ts');

// Ensure output directory exists
if (!existsSync(OUTPUT_DIR)) {
  mkdirSync(OUTPUT_DIR, { recursive: true });
}

async function main() {
  console.log('🔍 Checking for OpenAPI spec...');
  
  if (!existsSync(OPENAPI_PATH)) {
    console.warn(`⚠️  OpenAPI spec not found at: ${OPENAPI_PATH}`);
    console.warn('   Expected Laravel to generate it via: php artisan l5-swagger:generate');
    console.warn('   Using placeholder types instead.');
    
    // Create a minimal placeholder that re-exports the manual types
    const placeholder = `/**
 * GENERATED TYPES PLACEHOLDER
 * 
 * OpenAPI spec not found at: ${OPENAPI_PATH}
 * Run 'php artisan l5-swagger:generate' in backend/ to generate real types.
 * 
 * This file re-exports the manual types from ../api/index.ts
 */

export * from '../api';`;
    
    writeFileSync(OUTPUT_PATH, placeholder);
    console.log(`✅ Placeholder written to ${OUTPUT_PATH}`);
    return;
  }

  console.log(`📖 Reading OpenAPI spec from: ${OPENAPI_PATH}`);
  
  try {
    console.log('🔧 Generating TypeScript types using openapi-typescript CLI...');
    
    // Use CLI directly - the programmatic API has issues with astToString
    const result = spawnSync('npx', [
      'openapi-typescript',
      OPENAPI_PATH,
      '--enum', 'as-const'
    ], {
      cwd: ROOT_DIR,
      encoding: 'utf-8',
      stdio: 'pipe',
      shell: true
    });
    
    if (result.error) {
      throw result.error;
    }
    
    if (result.status !== 0) {
      console.error('❌ CLI error:', result.stderr);
      throw new Error(`openapi-typescript CLI failed with code ${result.status}`);
    }
    
    const types = result.stdout;
    
    // DEBUG: Log the output
    console.log('🔍 DEBUG: CLI output length:', types.length);
    console.log('   Preview:', types.slice(0, 200));
    
    // Write generated types
    const header = `/**
 * GENERATED FROM OPENAPI SPEC - DO NOT EDIT MANUALLY
 * 
 * Source: ${OPENAPI_PATH}
 * Generated: ${new Date().toISOString()}
 * Generator: openapi-typescript (via CLI)
 * 
 * Run 'pnpm --filter types generate' to regenerate.
 */

`;
    
    writeFileSync(OUTPUT_PATH, header + types);
    console.log(`✅ Types generated at ${OUTPUT_PATH}`);
    console.log(`✅ Types generated at ${OUTPUT_PATH}`);
    
    // Also update the main api/index.ts to re-export generated types
    updateMainApiIndex();
    
  } catch (error) {
    console.error('❌ Failed to generate types:', error);
    process.exit(1);
  }
}

function updateMainApiIndex() {
  const mainApiPath = resolve(OUTPUT_DIR, 'index.ts');
  const currentContent = readFileSync(mainApiPath, 'utf-8');
  
  // Check if already importing generated
  if (currentContent.includes("from './generated'")) {
    return; // Already updated
  }
  
  // Replace the placeholder comment with actual import
  const updatedContent = currentContent.replace(
    /\/\/ Placeholder types until OpenAPI generation is set up[\s\S]*?\/\/ ============================================/,
    `// Generated types from OpenAPI spec (backend/storage/api-docs/api-docs.json)
export * from './generated';

// ============================================`
  );
  
  writeFileSync(mainApiPath, updatedContent);
  console.log(`🔄 Updated ${mainApiPath} to re-export generated types`);
}

main().catch(console.error);